(()=>{
'use strict';
if(window.GTAVModConverter)return;
const by=(s,r=document)=>r.querySelector(s);
const all=(s,r=document)=>[...r.querySelectorAll(s)];
const enc=new TextEncoder();
const dec=new TextDecoder('utf-8',{fatal:false});
const MAX_INSPECT=512*1024;
const SCRIPT_EXT=/\.(asi|dll|exe|dylib|so|bat|cmd|ps1|vbs)$/i;
const MAP_EXT=/\.(ymap|ytyp)$/i;
const ASSET_EXT=/\.(ydd|ydr|yft|ytd|ymt|ybn|ycd|ypt)$/i;
const TEXT_EXT=/\.(oxt|gxt2)$/i;
const CONFIG_EXT=/\.(meta|xml|dat|cfg|ini|json|txt)$/i;
const ARCHIVE_EXT=/\.(zip|oiv|rar|7z)$/i;
const RPF_EXT=/\.rpf$/i;
const ZIP_SIG={EOCD:0x06054b50,CENTRAL:0x02014b50,LOCAL:0x04034b50};
const OPEN=0x4e45504f, AES=0x0ffffff9, NG=0x0fefffff, DEFAULT=0x0fffffff;

const crcTable=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=(c&1)?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
async function crc32(file){let crc=0xffffffff;const chunk=4*1024*1024;for(let o=0;o<file.size;o+=chunk){const u=new Uint8Array(await file.slice(o,Math.min(file.size,o+chunk)).arrayBuffer());for(const b of u)crc=crcTable[(crc^b)&255]^(crc>>>8)}return (crc^0xffffffff)>>>0}
function u16(v){const a=new Uint8Array(2);new DataView(a.buffer).setUint16(0,v,true);return a}
function u32(v){const a=new Uint8Array(4);new DataView(a.buffer).setUint32(0,v>>>0,true);return a}
function concat(parts){let n=0;for(const p of parts)n+=p.length;const out=new Uint8Array(n);let o=0;for(const p of parts){out.set(p,o);o+=p.length}return out}
function cleanName(v){return (v||'mod').replace(/\.[^.]+$/,'').normalize('NFKD').replace(/[^a-zA-Z0-9 _.-]+/g,'').trim().replace(/[ .]+/g,'-').replace(/-+/g,'-').slice(0,64)||'mod'}
function fmt(n){if(!Number.isFinite(n))return'—';const u=['B','KB','MB','GB'];let i=0,v=n;while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v>=100||i===0?v.toFixed(0):v.toFixed(1)} ${u[i]}`}
function levelLabel(level){return level==='ok'?'Ready':level==='warn'?'Check needed':'Unsupported'}
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}

async function inspectRpf(file){const head=new Uint8Array(await file.slice(0,16).arrayBuffer());if(head.length<16)return{valid:false,reason:'The archive is too small to be an RPF7 file.'};const ascii=String.fromCharCode(...head.slice(0,4));const dv=new DataView(head.buffer,head.byteOffset,head.byteLength);const values=[dv.getUint32(12,true),dv.getUint32(12,false)];const validMagic=ascii==='RPF7'||ascii==='7FPR'||dv.getUint32(0,true)===0x52504637||dv.getUint32(0,false)===0x52504637;if(!validMagic)return{valid:false,reason:`${file.name} does not have an RPF7 header.`};let encryption='Unknown',allowed=false,raw=values[0];for(const v of values){if(v===0){encryption='None';allowed=true;raw=v;break}if(v===OPEN){encryption='OPEN';allowed=true;raw=v;break}if(v===AES){encryption='AES';raw=v;break}if(v===NG||v===DEFAULT){encryption='NG / PC encrypted';raw=v;break}}
 return{valid:true,encryption,allowed,raw,magic:'RPF7',reason:allowed?'RPF7 archive is readable by the port.':'This RPF is encrypted for the PC. The launcher indicates that replacement archives must be converted on a computer first.'};
}

async function parseZip(file){const tailLen=Math.min(file.size,65557);const tail=new Uint8Array(await file.slice(file.size-tailLen).arrayBuffer());const dv=new DataView(tail.buffer,tail.byteOffset,tail.byteLength);let e=-1;for(let i=tail.length-22;i>=0;i--){if(dv.getUint32(i,true)===ZIP_SIG.EOCD){e=i;break}}if(e<0)throw new Error('ZIP end directory was not found.');const count=dv.getUint16(e+10,true),size=dv.getUint32(e+12,true),offset=dv.getUint32(e+16,true);if(count===0xffff||size===0xffffffff||offset===0xffffffff)throw new Error('ZIP64 packages are not inspected in the browser yet. Import the original archive directly in the launcher.');if(size>MAX_INSPECT*32)throw new Error('The ZIP directory is unusually large. Import the original archive directly in the launcher.');const central=new Uint8Array(await file.slice(offset,offset+size).arrayBuffer());const cd=new DataView(central.buffer,central.byteOffset,central.byteLength);let p=0;const entries=[];for(let i=0;i<count&&p+46<=central.length;i++){if(cd.getUint32(p,true)!==ZIP_SIG.CENTRAL)break;const flags=cd.getUint16(p+8,true),method=cd.getUint16(p+10,true),crc=cd.getUint32(p+16,true),compressed=cd.getUint32(p+20,true),uncompressed=cd.getUint32(p+24,true),nameLen=cd.getUint16(p+28,true),extraLen=cd.getUint16(p+30,true),commentLen=cd.getUint16(p+32,true),localOffset=cd.getUint32(p+42,true);const name=dec.decode(central.slice(p+46,p+46+nameLen));entries.push({name,flags,method,crc,compressed,uncompressed,localOffset});p+=46+nameLen+extraLen+commentLen}if(!entries.length)throw new Error('No readable files were found in this ZIP.');return entries}
async function zipDataSlice(file,entry){const head=new Uint8Array(await file.slice(entry.localOffset,entry.localOffset+30).arrayBuffer());if(head.length<30||new DataView(head.buffer).getUint32(0,true)!==ZIP_SIG.LOCAL)throw new Error('The selected ZIP has an invalid local file header.');const dv=new DataView(head.buffer),nameLen=dv.getUint16(26,true),extraLen=dv.getUint16(28,true),start=entry.localOffset+30+nameLen+extraLen;return file.slice(start,start+entry.compressed)}
function localHeader(name,method,crc,compressed,uncompressed){const n=enc.encode(name);return concat([u32(ZIP_SIG.LOCAL),u16(20),u16(0x0800),u16(method),u16(0),u16(0),u32(crc),u32(compressed),u32(uncompressed),u16(n.length),u16(0),n])}
function centralHeader(name,method,crc,compressed,uncompressed,offset){const n=enc.encode(name);return concat([u32(ZIP_SIG.CENTRAL),u16(20),u16(20),u16(0x0800),u16(method),u16(0),u16(0),u32(crc),u32(compressed),u32(uncompressed),u16(n.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(offset),n])}
function eocd(count,size,offset){return concat([u32(ZIP_SIG.EOCD),u16(0),u16(0),u16(count),u16(count),u32(size),u32(offset),u16(0)])}
async function makeStoredZip(files,outName){const parts=[],centrals=[];let offset=0;for(const item of files){const file=item.file||item, name=item.name||file.name, crc=await crc32(file), size=file.size;if(size>0xffffffff)throw new Error('Files above 4 GB need ZIP64 and cannot be packaged in Safari yet.');const h=localHeader(name,0,crc,size,size);parts.push(h,file);centrals.push(centralHeader(name,0,crc,size,size,offset));offset+=h.length+size}const central=concat(centrals);parts.push(central,eocd(files.length,central.length,offset));return new Blob(parts,{type:'application/zip'})}
async function normalizeZipEntry(source,entry,name='dlc.rpf'){if(entry.compressed>0xffffffff||entry.uncompressed>0xffffffff)throw new Error('This entry needs ZIP64 and cannot be normalized in the browser.');if(![0,8].includes(entry.method))throw new Error('This ZIP uses a compression method the browser converter will not rewrite.');const data=await zipDataSlice(source,entry);const local=localHeader(name,entry.method,entry.crc,entry.compressed,entry.uncompressed);const central=centralHeader(name,entry.method,entry.crc,entry.compressed,entry.uncompressed,0);return new Blob([local,data,central,eocd(1,central.length,local.length+entry.compressed)],{type:'application/zip'})}

function classifyNames(names){const lower=names.map(n=>n.toLowerCase()).filter(n=>!n.endsWith('/'));const scripts=lower.filter(n=>SCRIPT_EXT.test(n));const dlc=lower.filter(n=>/(^|\/)dlc\.rpf$/i.test(n));const assembly=lower.some(n=>/(^|\/)assembly\.xml$/i.test(n));const maps=lower.filter(n=>MAP_EXT.test(n));const text=lower.filter(n=>TEXT_EXT.test(n));const assets=lower.filter(n=>ASSET_EXT.test(n));const configs=lower.filter(n=>CONFIG_EXT.test(n));let kind='Archive',level='warn',message='The launcher can import this archive, but the browser could not identify a specific mod layout.';if(assembly){kind='OpenIV package';level='ok';message='This is an OpenIV package. The developer launcher imports .oiv/.zip packages directly.'}else if(dlc.length){kind='Add-on DLC pack';level=scripts.length?'warn':'ok';message=`Found ${dlc.length} dlc.rpf file${dlc.length>1?'s':''}. The launcher supports add-on packs from its MODS importer.`}else if(maps.length){kind='Map / YMAP mod';level=scripts.length?'warn':'ok';message='Map files are supported by the launcher importer.'}else if(text.length){kind='Language / text mod';level=scripts.length?'warn':'ok';message='Text and language files are handled by the launcher importer.'}else if(assets.length||configs.length){kind='Loose-file replacement';level=scripts.length?'warn':'ok';message='The archive contains GTA V assets/config files that the launcher can inspect and import.'}if(scripts.length&&!dlc.length&&!assembly&&!maps.length&&!text.length&&!assets.length&&!configs.length){kind='Script mod';level='bad';message='ASI/DLL/desktop script mods are not executable on this ARM64 iOS port.'}return{kind,level,message,scripts,dlc,assembly,maps,text,assets,configs}}

async function analyze(files){if(!files.length)throw new Error('Choose a mod first.');if(files.length>1){const names=files.map(f=>f.name),c=classifyNames(names);if(c.scripts.length&&!c.maps.length&&!c.text.length&&!c.assets.length&&!c.configs.length)return{...c,mode:'blocked',files};return{...c,kind:c.kind==='Archive'?'Loose mod files':c.kind,level:c.level==='bad'?'bad':'ok',message:'These files can be packaged as a ZIP for the launcher importer.',mode:'pack-files',files}}
 const file=files[0],name=file.name,ext=(name.match(/\.[^.]+$/)||[''])[0].toLowerCase();if(SCRIPT_EXT.test(name))return{kind:'Script mod',level:'bad',message:'This desktop binary cannot run on the ARM64 iOS port. It needs source-level porting, not repackaging.',mode:'blocked',files};
 if(ext==='.rar'||ext==='.7z')return{kind:ext.slice(1).toUpperCase()+' archive',level:'ok',message:`The developer launcher explicitly accepts ${ext} files. No conversion is required; import the original file in MODS › IMPORT MOD.`,mode:'direct',files};
 if(ext==='.oiv'||ext==='.zip'){const entries=await parseZip(file);const c=classifyNames(entries.map(e=>e.name));const dlcEntries=entries.filter(e=>/(^|\/)dlc\.rpf$/i.test(e.name));if(c.level==='bad')return{...c,mode:'blocked',files,entries};if(c.assembly)return{...c,mode:'direct',files,entries,message:'This OpenIV package is already supported by the developer launcher. Import the original file directly.'};if(dlcEntries.length===1&&dlcEntries[0].name.toLowerCase()!=='dlc.rpf')return{...c,mode:'normalize-dlc',files,entries,entry:dlcEntries[0],message:'A nested dlc.rpf was found. The converter can normalize it to a clean launcher import ZIP.'};return{...c,mode:'direct',files,entries,message:c.message+' No repackaging is required.'}}
 if(RPF_EXT.test(name)){const rpf=await inspectRpf(file);if(!rpf.valid)return{kind:'RPF archive',level:'bad',message:rpf.reason,mode:'blocked',files,rpf};if(!rpf.allowed)return{kind:name.toLowerCase()==='dlc.rpf'?'Add-on DLC pack':'Replacement RPF',level:'bad',message:rpf.reason,mode:'blocked',files,rpf};return{kind:name.toLowerCase()==='dlc.rpf'?'Add-on DLC pack':'Replacement RPF',level:'ok',message:`${rpf.magic} · ${rpf.encryption}. The converter can wrap this archive in a launcher-importable ZIP.`,mode:'pack-rpf',files,rpf}}
 const c=classifyNames([name]);if(c.level==='bad')return{...c,mode:'blocked',files};if(MAP_EXT.test(name)||ASSET_EXT.test(name)||TEXT_EXT.test(name)||CONFIG_EXT.test(name))return{...c,kind:'Loose mod file',level:'ok',message:'This loose mod file can be packaged as a ZIP for the launcher importer.',mode:'pack-files',files};return{kind:'Unknown mod file',level:'bad',message:'This file is not one of the mod types confirmed in the developer launcher.',mode:'blocked',files};
}

function inject(){if(by('#mod-converter'))return;const anchor=by('.mods-languages');if(!anchor)return;const sec=document.createElement('section');sec.id='mod-converter';sec.className='mod-converter';sec.innerHTML=`
 <div class="mod-converter-copy"><span class="eyebrow">LAUNCHER TOOL</span><h2>Mod converter.</h2><p>Check a GTA V mod against the import paths built into this iOS launcher. Supported files are prepared without uploading them anywhere.</p><div class="converter-proof"><span>Launcher-native</span><span>Local processing</span><span>No custom format</span></div></div>
 <div class="mod-converter-work"><input id="mod-converter-input" type="file" multiple accept=".zip,.oiv,.rar,.7z,.rpf,.ymap,.ytyp,.ydd,.ydr,.yft,.ytd,.ymt,.ybn,.ycd,.ypt,.meta,.xml,.dat,.cfg,.ini,.json,.txt,.oxt,.gxt2,.asi,.dll" hidden>
  <button class="converter-drop" id="mod-converter-pick" type="button"><span class="converter-plus">+</span><span><b>Select a mod</b><small>.zip · .oiv · .rar · .7z · .rpf · loose files</small></span><svg class="icon" aria-hidden="true"><use href="assets/icons.svg#arrow-right"></use></svg></button>
  <p class="converter-privacy">Analyzed in your browser. The selected files are not uploaded to this website.</p>
  <div class="converter-result" id="mod-converter-result" hidden aria-live="polite">
   <div class="converter-result-head"><div><span id="converter-state">ANALYZING</span><h3 id="converter-file">—</h3></div><b id="converter-badge">—</b></div>
   <div class="converter-facts"><div><span>Detected</span><strong id="converter-kind">—</strong></div><div><span>Size</span><strong id="converter-size">—</strong></div><div><span>Launcher action</span><strong id="converter-action">—</strong></div></div>
   <p id="converter-message"></p>
   <div class="converter-warning" id="converter-warning" hidden></div>
   <div class="converter-actions"><button type="button" id="converter-convert" class="mods-download" hidden><span>Prepare for launcher</span><svg class="icon" aria-hidden="true"><use href="assets/icons.svg#arrow-right"></use></svg></button><button type="button" id="converter-another">Choose another</button></div>
  </div>
 </div>`;anchor.insertAdjacentElement('beforebegin',sec);
 const input=by('#mod-converter-input'),pick=by('#mod-converter-pick'),result=by('#mod-converter-result'),convert=by('#converter-convert'),another=by('#converter-another');let current=null;
 pick.addEventListener('click',()=>input.click());another.addEventListener('click',()=>input.click());
 input.addEventListener('change',async()=>{const files=[...input.files];if(!files.length)return;result.hidden=false;convert.hidden=true;current=null;result.dataset.level='';by('#converter-state').textContent='ANALYZING';by('#converter-file').textContent=files.length===1?files[0].name:`${files.length} files selected`;by('#converter-badge').textContent='Checking';by('#converter-kind').textContent='—';by('#converter-size').textContent=fmt(files.reduce((n,f)=>n+f.size,0));by('#converter-action').textContent='Inspecting';by('#converter-message').textContent='Reading file structure and launcher compatibility…';by('#converter-warning').hidden=true;try{const analysis=await analyze(files);current=analysis;result.dataset.level=analysis.level;by('#converter-state').textContent='ANALYSIS COMPLETE';by('#converter-badge').textContent=levelLabel(analysis.level);by('#converter-kind').textContent=analysis.kind;by('#converter-action').textContent=analysis.mode==='direct'?'Import original':analysis.mode==='blocked'?'Not convertible here':analysis.mode==='normalize-dlc'?'Normalize ZIP':'Create import ZIP';by('#converter-message').textContent=analysis.message;const warnings=[];if(analysis.scripts?.length)warnings.push(`${analysis.scripts.length} desktop script/binary file${analysis.scripts.length>1?'s':''} detected; those files will not run on iOS.`);if(analysis.rpf&&!analysis.rpf.allowed)warnings.push(`RPF encryption: ${analysis.rpf.encryption}.`);if(warnings.length){const w=by('#converter-warning');w.textContent=warnings.join(' ');w.hidden=false}convert.hidden=!['pack-rpf','pack-files','normalize-dlc'].includes(analysis.mode)}catch(err){result.dataset.level='bad';by('#converter-state').textContent='COULD NOT INSPECT';by('#converter-badge').textContent='Check needed';by('#converter-kind').textContent='Archive';by('#converter-action').textContent='Import original';by('#converter-message').textContent=err?.message||'This mod could not be inspected in the browser.';current=null}});
 convert.addEventListener('click',async()=>{if(!current)return;const old=convert.querySelector('span').textContent;convert.disabled=true;convert.querySelector('span').textContent='Preparing…';try{let blob;const base=cleanName(current.files[0]?.name||'mod');if(current.mode==='pack-rpf')blob=await makeStoredZip([{file:current.files[0],name:current.files[0].name.toLowerCase()==='dlc.rpf'?'dlc.rpf':current.files[0].name}],base);else if(current.mode==='pack-files')blob=await makeStoredZip(current.files.map(f=>({file:f,name:f.webkitRelativePath||f.name})),base);else if(current.mode==='normalize-dlc')blob=await normalizeZipEntry(current.files[0],current.entry,'dlc.rpf');else return;download(blob,`${base}-launcher.zip`);by('#converter-action').textContent='ZIP prepared';by('#converter-message').textContent='Done. In the GTA V launcher, open MODS › IMPORT MOD and select the ZIP you just saved.'}catch(err){const w=by('#converter-warning');w.textContent=err?.message||'The package could not be created.';w.hidden=false}finally{convert.disabled=false;convert.querySelector('span').textContent=old}});
 window.GTAVModConverter={analyze,inspectRpf,parseZip,open:()=>input.click()};
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',inject,{once:true});else inject();
})();
